// C12: a failed write's status shows the error glyph, not the add (+) glyph the icon lookup fell back to.
test('a failed write shows an error mark beside its status', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'));
	await waitForRoute(page, 'update');
	await page.route((url) => url.pathname.endsWith('/update'), (route) => (route.request().method() === 'POST'
		? route.abort('failed') : route.continue()));
	await page.locator('#update-editor .CodeMirror').evaluate((element) =>
		element.CodeMirror.setValue('INSERT DATA { <urn:c12> <urn:p> "x" }'));
	await page.locator('#update-form [type="submit"]').click();
	const status = page.locator('#update-form .workbench-submit-status');
	await expect(status).toHaveAttribute('data-state', 'failed');
	const glyph = await status.locator('[data-workbench-icon="error"] path').getAttribute('d');
	expect(glyph, 'not the add glyph').not.toBe('M12 5v14M5 12h14');
	expect(glyph).toBe('M12 3.5a8.5 8.5 0 1 0 0 17 8.5 8.5 0 0 0 0-17ZM12 8v5m0 3h.01');
});

