// C13 (client): a write refused with the server's own explanation (a SHACL validation report) shows that explanation
// whole, line by line, instead of a 300-character cut of it squeezed onto one line.
test('a SHACL refusal of Add RDF shows the server\'s whole explanation, line by line', async ({ page, request }) => {
	const repositoryId = uniqueRepositoryId('workbench-round3-shacl');
	const repositoryUrl = `${serverBaseUrl()}/repositories/${encodeURIComponent(repositoryId)}`;
	const created = await request.put(repositoryUrl, { headers: { 'Content-Type': 'text/turtle' }, data: `
		@prefix config: <tag:rdf4j.org,2023:config/> .
		[] a config:Repository ; config:rep.id "${repositoryId}" ; config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
			config:sail.impl [ config:sail.type "rdf4j:ShaclSail" ; config:delegate [ config:sail.type "openrdf:MemoryStore" ] ] ] .` });
	expect([200, 201, 204]).toContain(created.status());
	try {
		const shapes = await request.post(`${repositoryUrl}/statements?context=${encodeURIComponent('<http://rdf4j.org/schema/rdf4j#SHACLShapeGraph>')}`, {
			headers: { 'Content-Type': 'text/turtle' },
			data: `@prefix sh: <http://www.w3.org/ns/shacl#> . @prefix ex: <http://example.org/> .
				ex:PersonShape a sh:NodeShape ; sh:targetClass ex:Person ;
					sh:property [ sh:path ex:age ; sh:datatype <http://www.w3.org/2001/XMLSchema#integer> ; sh:maxCount 1 ] .`
		});
		expect([200, 204]).toContain(shapes.status());
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(repositoryPageUrl(repositoryId, 'add'));
		await waitForRoute(page, 'add');
		await page.locator('label[for="source-text"]').click();
		await page.locator('#text').fill('@prefix ex: <http://example.org/> .\nex:p2 a ex:Person ; ex:age "x" .');
		await page.locator('#add-upload-actions input[type="submit"]').click();
		const status = page.locator('#workbench-outlet .workbench-submit-status');
		await expect(status).toHaveAttribute('data-state', 'failed');
		const shown = await status.evaluate((element) => {
			const range = document.createRange();
			range.selectNodeContents(element);
			const tops = new Set(Array.from(range.getClientRects()).filter((rect) => rect.width > 0)
				.map((rect) => Math.round(rect.top)));
			return { text: element.textContent, lines: tops.size };
		});
		expect(shown.text, 'the focus node is named').toMatch(/p2/);
		expect(shown.text.trim().endsWith('…'), 'not cut short').toBe(false);
		expect(shown.text.split('\n').filter((line) => line.trim()).length, 'the report keeps its lines').toBeGreaterThan(1);
		expect(shown.lines, 'shown on more than one line').toBeGreaterThan(1);
	} finally {
		await deleteRepository(request, serverBaseUrl(), repositoryId);
	}
});

