// C32f: a query the user cancelled is not shown as a red error.
test('a cancelled query is reported plainly, not as an error', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await waitForRoute(page, 'query');
	let release;
	const released = new Promise((resolve) => { release = resolve; });
	await page.route(new RegExp(`/repositories/${REPOSITORY_ID}/query$`), async (route) => {
		const parameters = new URLSearchParams(route.request().postData() || '');
		if (route.request().method() === 'POST' && parameters.get('action') === 'exec') {
			await released;
			return route.abort('aborted').catch(() => {});
		}
		return route.fallback();
	});
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('SELECT * WHERE { ?s ?p ?o }'));
	await page.locator('#exec').click();
	await expect(page.locator('#query-cancel')).toBeEnabled();
	await page.locator('#query-cancel').click();
	const error = page.locator('#query-results .query-result-error');
	await expect(error).toBeVisible();
	await expect(error).toContainText(/cancel/i);
	await expect(error).not.toHaveClass(/workbench-callout--error/);
	release();
});

