// C23: a saved query's name is checked as it changes by any means (typing, autofill, drop), may use the letters of any
// language, and a name that cannot be saved says why.
test('the Save query name is checked on every change and says why it cannot be used', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await waitForRoute(page, 'query');
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('ASK {}'));
	await page.locator('#save-query-toggle').click();
	const name = page.locator('#query-name');
	const save = page.locator('#save');
	// fill() changes the value without key presses, as autofill or a drop does.
	await name.fill('Spørring på norsk');
	await expect(save).toBeEnabled();
	await name.fill('bad/name');
	await expect(save).toBeDisabled();
	await expect(page.locator('#save-feedback')).toContainText(/letters, digits, spaces/);
	await name.fill('good_name-1');
	await expect(save).toBeEnabled();
	await expect(page.locator('#save-feedback')).toHaveText('');
});

// C24: Chrome and Edge on macOS report the platform as 'macOS' (navigator.userAgentData): the shortcut is Cmd+Enter.
test('the Execute shortcut is shown as Cmd on macOS also where the platform says "macOS"', async ({ browser }) => {
	const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
	const page = await context.newPage();
	await page.addInitScript(() => {
		Object.defineProperty(navigator, 'userAgentData', { configurable: true,
			value: { platform: 'macOS', mobile: false, brands: [] } });
		Object.defineProperty(navigator, 'platform', { configurable: true, value: '' });
	});
	try {
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
		await waitForRoute(page, 'query');
		await expect(page.locator('#query-form')).toContainText('⌘');
		await expect(page.locator('#query-form')).not.toContainText('Ctrl');
	} finally {
		await context.close();
	}
});

// C15 (client decoding): the credentials cookie is base64 of the UTF-8 bytes of "user:password"; a user name outside
// Latin-1 is shown as itself.
test('a signed-in user name outside Latin-1 is shown as itself', async ({ page, context }) => {
	const user = 'José✓';
	await context.addCookies([{ name: 'server-user-password', url: workbenchBaseUrl() + '/',
		value: Buffer.from(user + ':pw', 'utf8').toString('base64') }]);
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
	await waitForRoute(page, 'summary');
	await page.locator('#workbench-repository-switcher').click();
	await expect(page.locator('#workbench-repository-popover .workbench-popover__server')).toContainText(user);
});

// C8 (stale list): the server refuses an add whose prefix another page bound meanwhile, naming the namespace it is bound
// to; the page then asks about that one and sends the replacement when confirmed.
test('a prefix bound meanwhile is asked about with the namespace the server names', async ({ page, request }) => {
	const repositoryId = uniqueRepositoryId('workbench-round3-namespaces');
	await createSeededRepository(request, serverBaseUrl(), repositoryId, { graphs: [] });
	try {
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(repositoryPageUrl(repositoryId, 'namespaces'));
		await waitForRoute(page, 'namespaces');
		const posts = [];
		await page.route(/\/namespaces$/, async (route) => {
			const sent = route.request();
			if (sent.method() !== 'POST') {
				return route.fallback();
			}
			const parameters = new URLSearchParams(sent.postData() || '');
			posts.push(Object.fromEntries(parameters));
			if (parameters.get('overwrite') === 'true') {
				return route.fallback();
			}
			const records = [
				{ type: 'head', version: 1 }, { type: 'view', id: 'namespaces' },
				{ type: 'vars', values: ['prefix', 'namespace'] }, { type: 'links', values: ['info'] },
				{ type: 'metadata', values: { 'error-message': "Prefix 'c8s' is already defined",
					'existing-namespace': 'http://bound-meanwhile.example/' } },
				{ type: 'rows', values: [[{ kind: 'literal', value: 'c8s' }, { kind: 'literal', value: 'http://bound-meanwhile.example/' }]] },
				{ type: 'end' }
			];
			return route.fulfill({ status: 400, contentType: 'application/vnd.rdf4j.workbench+ndjson;charset=UTF-8',
				body: records.map((record) => JSON.stringify(record)).join('\n') + '\n' });
		});
		await addNamespaceRow(page, 'c8s', 'http://mine.example/');
		const dialog = page.getByRole('dialog', { name: 'Replace prefix c8s?' });
		await expect(dialog).toContainText("Prefix 'c8s' is already defined as <http://bound-meanwhile.example/>. Replace it?");
		await dialog.getByRole('button', { name: 'Replace' }).click();
		await expect.poll(() => posts.length).toBe(2);
		expect(posts[1]).toEqual(expect.objectContaining({ prefix: 'c8s', namespace: 'http://mine.example/', overwrite: 'true' }));
		await expect(page.locator('#namespaces-results tbody')).toContainText('http://mine.example/');
		expect((await namespacesOf(request, repositoryId)).c8s).toBe('http://mine.example/');
	} finally {
		await deleteRepository(request, serverBaseUrl(), repositoryId);
	}
});

// C32c (client): when the server cannot count a repository (an unreachable SPARQL endpoint), the Summary says so and why
// instead of showing a bare '—'.
test('the Summary says why its counts are not available', async ({ page }) => {
	await page.route(/\/summary\?counts=true$/, (route) => route.fulfill({ status: 200,
		contentType: 'application/vnd.rdf4j.workbench+ndjson;charset=UTF-8',
		body: [
			{ type: 'head', version: 1 }, { type: 'view', id: 'summary' },
			{ type: 'vars', values: ['size', 'contexts'] }, { type: 'links', values: ['info'] },
			{ type: 'metadata', values: { 'counts-failed': 'Connection refused' } },
			{ type: 'rows', values: [[null, null]] }, { type: 'end' }
		].map((record) => JSON.stringify(record)).join('\n') + '\n' }));
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
	await waitForRoute(page, 'summary');
	await expect(page.locator('#workbench-summary')).toContainText('Counts are not available: Connection refused');
	await expect(page.locator('#workbench-summary')).not.toContainText('Counting…');
});

// C28: in compare mode the menu opens as a flyout from ≡; using it to go to another page closes it, so the Query page
// shown again has its menu tucked away as before.
test('the compare-mode menu flyout used to leave the Query page is closed when the page comes back', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await waitForRoute(page, 'query');
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('SELECT * WHERE { ?s ?p ?o } LIMIT 3'));
	await page.locator('#explain-trigger').click();
	await expect(page.locator('#compare-toggle')).toBeEnabled();
	await page.locator('#compare-toggle').click();
	await expect(page.locator('body')).toHaveClass(/query-compare-mode/);
	const toggle = page.locator('#query-sidebar-toggle');
	await toggle.click();
	await expect(toggle).toHaveAttribute('aria-expanded', 'true');
	await page.locator('#navigation').getByRole('link', { name: 'Summary', exact: true }).click();
	await waitForRoute(page, 'summary', { url: (url) => url.pathname.endsWith('/summary') });
	await page.locator('#navigation a[href="query"]').click();
	await waitForRoute(page, 'query', { url: (url) => url.pathname.endsWith('/query') });
	await expect(page.locator('body')).toHaveClass(/query-compare-mode/);
	await expect(toggle).toHaveAttribute('aria-expanded', 'false');
	await expect(page.locator('body')).not.toHaveClass(/query-compare-nav-open/);
});

// C30: deleting a saved query leaves no '?delete=urn:…' in the address bar or the history.
test('deleting a saved query leaves no delete parameter in the address', async ({ page }) => {
	const queryName = `round3-delete-${process.pid}-${Date.now().toString(36)}`;
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await waitForRoute(page, 'query');
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('ASK {}'));
	await page.locator('#save-query-toggle').click();
	await page.locator('#query-name').fill(queryName);
	await page.locator('#save').click();
	await expect(page.locator('#save-feedback')).toHaveText('Query saved.');
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'saved-queries'));
	await waitForRoute(page, 'saved-queries');
	const row = page.locator('.saved-query-row').filter({ hasText: queryName });
	await row.locator('.saved-query-delete').click();
	await page.getByRole('dialog', { name: 'Delete saved query?' }).getByRole('button', { name: 'Delete' }).click();
	await expect(page.locator('.saved-query-row').filter({ hasText: queryName })).toHaveCount(0);
	expect(page.url()).not.toContain('delete=');
	const history = await page.evaluate(() => history.length);
	await page.goBack();
	await page.waitForTimeout(300);
	expect(page.url(), `Back (history ${history}) does not lead to a delete address`).not.toContain('delete=');
});

// C31: leaving the Query page by a full page load starts no IndexedDB work that the unload aborts (Firefox warns about
// every such transaction); the page flags its stored result instead, and cleanup in the next page deletes it.
test('a full page load after the Query page aborts no IndexedDB work and reclaims the rows', async ({ page }) => {
	const warnings = [];
	page.on('console', (message) => {
		if (/IndexedDB transaction .* aborted/i.test(message.text())) {
			warnings.push(message.text());
		}
	});
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
	await waitForRoute(page, 'query');
	await page.locator('.CodeMirror').first().evaluate((element, query) => element.CodeMirror.setValue(query),
		largeQuery());
	await page.locator('#exec').click();
	await expect(page.locator('#query-results .query-result-status')).toHaveText(/^12,000 rows · complete/,
		{ timeout: 30000 });
	const storeIds = (await storedResults(page)).databases;
	expect(storeIds, 'a result of 12,000 rows is stored in a database of its own').toHaveLength(1);

	await page.reload({ waitUntil: 'load' });
	await waitForRoute(page, 'query');
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
	await waitForRoute(page, 'summary');
	await page.goBack({ waitUntil: 'load' });
	await waitForRoute(page, 'query');
	await page.waitForTimeout(500);
	expect(warnings, 'no IndexedDB transaction aborted by a page load').toEqual([]);
	await expect.poll(async () => {
		const stored = await storedResults(page);
		return storeIds.filter((id) => stored.databases.includes(id) || id in stored.registry).length;
	}, { message: 'the rows of the page that was left are reclaimed' }).toBe(0);
});

// C32a: the Repositories list and the repository switcher are in ID order.
test('the Repositories list and the switcher list repositories in ID order', async ({ page, request }) => {
	const stamp = `${process.pid}-${Date.now().toString(36)}`;
	const ids = [`r3-zz-${stamp}`, `r3-aa-${stamp}`, `r3-mm-${stamp}`];
	for (const id of ids) {
		await createSeededRepository(request, serverBaseUrl(), id, { graphs: [] });
	}
	try {
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(`${workbenchBaseUrl()}/repositories`);
		await waitForRoute(page, 'repositories');
		const listed = (await page.locator('#repositories-results .workbench-repository-link').allTextContents())
			.map((text) => text.trim()).filter((text) => ids.includes(text));
		expect(listed).toEqual([...ids].sort());
		await expect(page.locator('#repositories-results thead th[data-repository-column="id"]')).toHaveAttribute('aria-sort', 'ascending');

		await page.goto(repositoryPageUrl(ids[0], 'summary'));
		await waitForRoute(page, 'summary');
		await page.locator('#workbench-repository-switcher').click();
		await expect(page.locator(`#workbench-repository-options a[data-repository-id="${ids[2]}"]`)).toBeVisible();
		const offered = (await page.locator('#workbench-repository-options a[data-repository-id]').evaluateAll((links) =>
			links.map((link) => link.getAttribute('data-repository-id')))).filter((id) => ids.includes(id));
		expect(offered).toEqual([...ids].sort());
	} finally {
		for (const id of ids) {
			await deleteRepository(request, serverBaseUrl(), id);
		}
	}
});

