// C32e: Clear has nothing to do on an empty repository and says so instead of offering the action.
test('Clear is not offered on an empty repository', async ({ page, request }) => {
	const repositoryId = uniqueRepositoryId('workbench-round3-empty');
	await createSeededRepository(request, serverBaseUrl(), repositoryId, { graphs: [] });
	try {
		await page.goto(repositoryPageUrl(repositoryId, 'clear'));
		await waitForRoute(page, 'clear');
		const clear = page.locator('#clear-form button[type="submit"]');
		await expect(page.locator('#clear-form select#context option').first()).toContainText('0 statements');
		await expect(clear).toBeDisabled();
		await expect(page.locator('#clear-form')).toContainText(/empty/i);
	} finally {
		await deleteRepository(request, serverBaseUrl(), repositoryId);
	}
});
